    else:
        # Fallback: connect the markers with a diagonal segment followed by
        # the remaining straight segment.
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        n = min(abs(r2-r1), abs(c2-c1))
        cells = [(r1 + dr*i, c1 + dc*i) for i in range(1, n)]
